import{_ as e,o as i,c as l,a2 as t}from"./chunks/framework.DQbZ8cc1.js";const b=JSON.parse('{"title":"BBS-GO 安装使用手册","description":"","frontmatter":{},"headers":[],"relativePath":"zh/docs/guide.md","filePath":"zh/docs/guide.md"}'),s={name:"zh/docs/guide.md"};function d(o,a,n,r,h,c){return i(),l("div",null,[...a[0]||(a[0]=[t(`<h1 id="bbs-go-安装使用手册" tabindex="-1">BBS-GO 安装使用手册 <a class="header-anchor" href="#bbs-go-安装使用手册" aria-label="Permalink to “BBS-GO 安装使用手册”">​</a></h1><h2 id="_1-系统要求" tabindex="-1">1. 系统要求 <a class="header-anchor" href="#_1-系统要求" aria-label="Permalink to “1. 系统要求”">​</a></h2><ul><li>操作系统：Windows / macOS / Linux</li><li>内存：建议 2GB+</li><li>数据库： <ul><li>生产环境建议 MySQL 8+</li><li>本地体验可用 SQLite</li></ul></li></ul><h2 id="_2-下载发布包" tabindex="-1">2. 下载发布包 <a class="header-anchor" href="#_2-下载发布包" aria-label="Permalink to “2. 下载发布包”">​</a></h2><p>发布地址：<a href="https://github.com/mlogclub/bbs-go/releases/latest" target="_blank" rel="noreferrer">https://github.com/mlogclub/bbs-go/releases/latest</a></p><table tabindex="0"><thead><tr><th>平台</th><th>文件名</th></tr></thead><tbody><tr><td>Windows</td><td><code>bbs-go-windows-x86_64.zip</code></td></tr><tr><td>macOS Intel</td><td><code>bbs-go-macos-amd64.zip</code></td></tr><tr><td>macOS Apple 芯片</td><td><code>bbs-go-macos-arm64.zip</code></td></tr><tr><td>Linux 64 位</td><td><code>bbs-go-linux-amd64.zip</code></td></tr><tr><td>Linux 32 位</td><td><code>bbs-go-linux-386.zip</code></td></tr></tbody></table><h2 id="_3-启动程序" tabindex="-1">3. 启动程序 <a class="header-anchor" href="#_3-启动程序" aria-label="Permalink to “3. 启动程序”">​</a></h2><p>解压后进入目录，运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux/macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bbs-go</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bbs-go.exe</span></span></code></pre></div><p>默认监听端口：<code>8082</code>。</p><h2 id="_4-首次安装" tabindex="-1">4. 首次安装 <a class="header-anchor" href="#_4-首次安装" aria-label="Permalink to “4. 首次安装”">​</a></h2><p>浏览器访问：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://localhost:8082/install</span></span></code></pre></div><p>安装向导步骤：</p><ol><li>选择语言（<code>en-US</code> / <code>zh-CN</code>）</li><li>选择数据库（MySQL 或 SQLite）</li><li>填写站点信息</li><li>创建管理员账号</li><li>完成安装</li></ol><p>安装完成后系统会自动初始化配置和数据。</p><h2 id="_5-访问地址" tabindex="-1">5. 访问地址 <a class="header-anchor" href="#_5-访问地址" aria-label="Permalink to “5. 访问地址”">​</a></h2><ul><li>前台：<code>http://localhost:8082/</code></li><li>后台：<code>http://localhost:8082/admin</code></li></ul><h2 id="_6-常见问题" tabindex="-1">6. 常见问题 <a class="header-anchor" href="#_6-常见问题" aria-label="Permalink to “6. 常见问题”">​</a></h2><h3 id="端口被占用" tabindex="-1">端口被占用 <a class="header-anchor" href="#端口被占用" aria-label="Permalink to “端口被占用”">​</a></h3><p>修改 <code>bbs-go.yaml</code> 中 <code>Port</code>，或停止占用进程。</p><h3 id="数据库连接失败" tabindex="-1">数据库连接失败 <a class="header-anchor" href="#数据库连接失败" aria-label="Permalink to “数据库连接失败”">​</a></h3><ul><li>MySQL：检查地址、端口、用户名、密码、数据库名</li><li>SQLite：建议直接在安装向导中选择 SQLite，无需手工建库</li></ul><h3 id="生产环境建议" tabindex="-1">生产环境建议 <a class="header-anchor" href="#生产环境建议" aria-label="Permalink to “生产环境建议”">​</a></h3><ul><li>使用 MySQL</li><li>使用 Nginx/Caddy 反代并开启 HTTPS</li><li>定期备份数据库和上传文件</li></ul><h2 id="_7-进阶文档" tabindex="-1">7. 进阶文档 <a class="header-anchor" href="#_7-进阶文档" aria-label="Permalink to “7. 进阶文档”">​</a></h2><ul><li><a href="./installation/index.html">安装与部署总览</a></li><li><a href="./installation/server/install.html">服务部署</a></li><li><a href="./installation/docker.html">Docker 部署</a></li></ul>`,27)])])}const m=e(s,[["render",d]]);export{b as __pageData,m as default};
